// Larping Moderation Badge 1.1

(function setupBadgeImageFixer() {
    const BADGE_IMG_SELECTOR = 'img[src*="/badge-icons/"]';
    function tryFix(img) {
        try {
            const src = img.getAttribute("src") || "";
            if (src.includes("/badge-icons/https://") || src.includes("/badge-icons/http://") || src.includes("/badge-icons/data:")) {
                const m = src.match(/\/badge-icons\/(.+?)(?:\.(?:png|webp|jpg|jpeg|gif))(?:\?|$)/i) || src.match(/\/badge-icons\/(.+)$/i);
                if (!m) return;
                let raw = m[1];
                try { raw = decodeURIComponent(raw); } catch {}
                raw = raw.replace(/%2F/gi, "/");
                if (/^(https?:|data:)/.test(raw)) {
                    img.referrerPolicy = "no-referrer";
                    img.loading = "eager";
                    img.decoding = "async";
                    img.src = raw;
                }
            }
        } catch {}
    }
    document.querySelectorAll(BADGE_IMG_SELECTOR).forEach(tryFix);
    const mo = new MutationObserver(muts => {
        for (const mut of muts) {
            mut.addedNodes.forEach(node => {
                if (node.nodeType !== 1) return;
                if (node.matches?.(BADGE_IMG_SELECTOR)) tryFix(node);
                node.querySelectorAll?.(BADGE_IMG_SELECTOR).forEach(tryFix);
            });
        }
    });
    mo.observe(document.documentElement, { childList: true, subtree: true });
})();

function addBadgesInOrder(badges) {
    const store = Vencord.Webpack.findStore("UserProfileStore");
    const orig = store.getUserProfile;
    store.getUserProfile = function (userId) {
        const profile = orig.apply(this, arguments);
        const currentUser = Vencord.Webpack.Common.UserStore.getCurrentUser();
        if (!profile || userId !== currentUser?.id) return profile;
        profile.badges = Array.isArray(profile.badges) ? profile.badges : [];
        badges.forEach((b, index) => {
            if (!profile.badges.some(x => x.id === b.id)) {
                profile.badges.splice(index, 0, {
                    id: b.id,
                    description: b.description,
                    icon: b.icon,
                    link: b.link || "#"
                });
            }
        });
        return profile;
    };
}

addBadgesInOrder([
    {
        id: "518379-moderator",
        description: "Official Moderator",
        icon: "data:image/gif;base64,"
    }
]);
